// Choose a small positive initial capacity (>=1)
int capacity = (int)(*FUZZ_PARAM(unsigned int) % 128u) + 1;

// Provide captureless function pointers compatible with c-string keys.
// Hash: djb2 over bytes until first '\0'.
auto hash = +[](void* key) -> unsigned long {
    const unsigned char* s = (const unsigned char*)key;
    if (!s) { return 0ul; }
    unsigned long h = 5381ul;
    while (*s) { h = ((h << 5) + h) + (unsigned long)(*s++); }
    return h;
};
// Compare: strcmp-like semantics; returns 0 when equal.
auto cmp = +[](void* a, void* b) -> int {
    const unsigned char* pa = (const unsigned char*)a;
    const unsigned char* pb = (const unsigned char*)b;
    if (pa == pb) { return 0; }
    if (!pa || !pb) { return pa ? 1 : (pb ? -1 : 0); }
    while (*pa && (*pa == *pb)) { ++pa; ++pb; }
    return (int)(*pa) - (int)(*pb);
};

// Allocate the struct table storage owned by the caller (fuzzer harness) and initialize it.
struct table* table = new struct table;  // caller-owned storage
if (!table) { FUZZ_BAIL(); }

// Initialize the hashtable instance
table_init(table, capacity, hash, cmp);

// Track state and key format for downstream stubs
FUZZ_SET_ATTR_INT(table, "initialized", 1);
FUZZ_SET_ATTR_STR(table, "key_fmt", "cstring");
FUZZ_SET_ATTR_INT(table, "has_known", 0);
FUZZ_SET_ATTR_PTR(table, "known_key", nullptr);
FUZZ_SET_ATTR_PTR(table, "known_value", nullptr);

// Validation: ensure table is marked initialized for later API usage
FUZZ_ASSERT(FUZZ_GET_ATTR_INT(table, "initialized") == 1, "table_init must set initialized state");

// Enforce precondition: table must be previously initialized
if (FUZZ_GET_ATTR_INT(table, "initialized") != 1) { FUZZ_BAIL(); }

// If we tracked any heap-allocated known key/value, release them now since the API
// is not expected to free user values.
{
    void* kptr = FUZZ_GET_ATTR_PTR(table, "known_key");
    void* vptr = FUZZ_GET_ATTR_PTR(table, "known_value");
    if (kptr) { delete[] (char*)kptr; FUZZ_SET_ATTR_PTR(table, "known_key", nullptr); }
    if (vptr) { delete[] (char*)vptr; FUZZ_SET_ATTR_PTR(table, "known_value", nullptr); }
    FUZZ_SET_ATTR_INT(table, "has_known", 0);
}

// Invoke the target function
table_free(table);

// Mark as deinitialized. The underlying storage is caller-owned; we drop it from pool.
FUZZ_SET_ATTR_INT(table, "initialized", 0);

// Validation: After free, the table should not be used unless reinitialized

// Enforce precondition: table must be previously initialized
if (FUZZ_GET_ATTR_INT(table, "initialized") != 1) { FUZZ_BAIL(); }

// Clear all entries; table remains usable
table_clear(table);

// If we had a tracked known key/value, they are no longer stored by the table.
void* kptr = FUZZ_GET_ATTR_PTR(table, "known_key");
void* vptr = FUZZ_GET_ATTR_PTR(table, "known_value");
if (kptr) { delete[] (char*)kptr; FUZZ_SET_ATTR_PTR(table, "known_key", nullptr); }
if (vptr) { delete[] (char*)vptr; FUZZ_SET_ATTR_PTR(table, "known_value", nullptr); }
FUZZ_SET_ATTR_INT(table, "has_known", 0);

// Validation: Table remains initialized and returned to pool
FUZZ_ASSERT(FUZZ_GET_ATTR_INT(table, "initialized") == 1, "table must remain initialized after clear");

// Preconditions: initialized table, using c-string key semantics matching our function pointers
if (FUZZ_GET_ATTR_INT(table, "initialized") != 1) { FUZZ_BAIL(); }
if (std::string(FUZZ_GET_ATTR_STR(table, "key_fmt")) != std::string("cstring")) { FUZZ_BAIL(); }

// Generate a random c-string key and ensure the buffer includes the null terminator for key_size
std::string key = FUZZ_PARAM_STR();
// Bound the key size for performance and to keep key_size within int
if (key.size() > 1023u) { key.resize(1023u); }
const void* key_buf = (const void*)key.c_str();
int key_size = (int)(key.size() + 1); // include null terminator for our strcmp-based cmp
if (key_size <= 0) { FUZZ_BAIL(); }

// Generate a small heap-allocated value buffer to store as the value pointer (user-managed)
std::string val_src = FUZZ_PARAM_STR();
if (val_src.size() > 255u) { val_src.resize(255u); }
int vlen = (int)val_src.size();
char* value = new char[vlen + 1];
if (!value) { FUZZ_BAIL(); }
for (int i = 0; i < vlen; ++i) { value[i] = val_src[i]; }
value[vlen] = '\0';

// Perform the insertion
_table_add(table, (void*)key_buf, key_size, (void*)value);

// Track this inserted key/value as a known pair for later remove/find validation.
// Make a heap copy of the key string so we can reuse it safely across stubs.
char* key_copy = new char[key_size];
if (!key_copy) { FUZZ_BAIL(); }
for (int i = 0; i < key_size; ++i) { key_copy[i] = ((const char*)key_buf)[i]; }

// If a previous known pair exists, free it to avoid leaks; we keep only the latest known pair.
void* prev_k = FUZZ_GET_ATTR_PTR(table, "known_key");
void* prev_v = FUZZ_GET_ATTR_PTR(table, "known_value");
if (prev_k) { delete[] (char*)prev_k; }
if (prev_v) { delete[] (char*)prev_v; }

FUZZ_SET_ATTR_PTR(table, "known_key", (void*)key_copy);
FUZZ_SET_ATTR_PTR(table, "known_value", (void*)value);
FUZZ_SET_ATTR_INT(table, "has_known", 1);

// Validation: key_size is positive and matches the copied buffer length by construction

// Preconditions: initialized table, using c-string keys
if (FUZZ_GET_ATTR_INT(table, "initialized") != 1) { FUZZ_BAIL(); }
if (std::string(FUZZ_GET_ATTR_STR(table, "key_fmt")) != std::string("cstring")) { FUZZ_BAIL(); }

int has_known = FUZZ_GET_ATTR_INT(table, "has_known");
const char* key_ptr = nullptr;
std::string fallback;
if (has_known) {
    key_ptr = (const char*)FUZZ_GET_ATTR_PTR(table, "known_key");
} else {
    // No tracked key; remove with a random c-string key (may or may not exist)
    fallback = FUZZ_PARAM_STR();
    if (fallback.size() > 1023u) { fallback.resize(1023u); }
    key_ptr = fallback.c_str();
}
if (!key_ptr) { FUZZ_BAIL(); }

// Perform the removal attempt
table_remove(table, (void*)key_ptr);

// If we removed the tracked key (best-effort assumption), drop our tracked heap objects
if (has_known) {
    void* kptr = FUZZ_GET_ATTR_PTR(table, "known_key");
    void* vptr = FUZZ_GET_ATTR_PTR(table, "known_value");
    if (kptr) { delete[] (char*)kptr; FUZZ_SET_ATTR_PTR(table, "known_key", nullptr); }
    if (vptr) { delete[] (char*)vptr; FUZZ_SET_ATTR_PTR(table, "known_value", nullptr); }
    FUZZ_SET_ATTR_INT(table, "has_known", 0);
}

// Validation: table remains initialized after removal
FUZZ_ASSERT(FUZZ_GET_ATTR_INT(table, "initialized") == 1, "table must remain initialized after remove");

// Preconditions: initialized table, using c-string keys
if (FUZZ_GET_ATTR_INT(table, "initialized") != 1) { FUZZ_BAIL(); }
if (std::string(FUZZ_GET_ATTR_STR(table, "key_fmt")) != std::string("cstring")) { FUZZ_BAIL(); }

int has_known = FUZZ_GET_ATTR_INT(table, "has_known");
const char* key_ptr = nullptr;
std::string fallback;
if (has_known) {
    key_ptr = (const char*)FUZZ_GET_ATTR_PTR(table, "known_key");
} else {
    // Probe a random key
    fallback = FUZZ_PARAM_STR();
    if (fallback.size() > 1023u) { fallback.resize(1023u); }
    key_ptr = fallback.c_str();
}
if (!key_ptr) { FUZZ_BAIL(); }

// Lookup
void* found = table_find(table, (void*)key_ptr);

// If we have a known inserted pair and we haven't cleared/removed, the lookup should succeed
if (has_known) {
    void* expected = FUZZ_GET_ATTR_PTR(table, "known_value");
    FUZZ_ASSERT(found == expected, "table_find must return the stored value for the known key");
}

// Validation: table remains initialized and usable
FUZZ_ASSERT(FUZZ_GET_ATTR_INT(table, "initialized") == 1, "table must remain initialized after find");
